// NOTE: generated with Claude Opus 4.8

import XCTest
import Foundation

import Spanker
import Hitch

// The encoder's byte layout was validated end-to-end against Apache Arrow
// (pyarrow) via a reference implementation. These Swift tests cover what can be
// checked without a Parquet reader in-process: structural invariants of the
// file envelope, plus an opt-in dump to disk (set PARQUET_OUT) so the real
// Swift output can be round-tripped through pyarrow/duckdb locally:
//
//   PARQUET_OUT=/tmp/out.parquet swift test --filter test_parquet_write_file
//   python3 validate.py /tmp/out.parquet
class ParquetEncoderTests: TestsBase {

    private func parquetBytes(_ json: String) -> [UInt8] {
        let data: Data? = json.parsed { $0?.toParquet() }
        return [UInt8](data ?? Data())
    }

    private func leU32(_ b: [UInt8], _ at: Int) -> UInt32 {
        return UInt32(b[at]) | (UInt32(b[at + 1]) << 8)
             | (UInt32(b[at + 2]) << 16) | (UInt32(b[at + 3]) << 24)
    }

    func test_parquet_envelope_magic() {
        let b = parquetBytes(#"[{"a":1,"b":"x"},{"a":2,"b":"y"}]"#)
        XCTAssertGreaterThan(b.count, 12)
        // Header and footer magic "PAR1".
        XCTAssertEqual(Array(b.prefix(4)), [0x50, 0x41, 0x52, 0x31])
        XCTAssertEqual(Array(b.suffix(4)), [0x50, 0x41, 0x52, 0x31])
    }

    func test_parquet_footer_length_is_consistent() {
        let b = parquetBytes(#"[{"a":1,"b":"x"},{"a":2,"b":"y"}]"#)
        let n = b.count
        // Layout: [PAR1][data...][metadata (metaLen bytes)][metaLen: u32 LE][PAR1]
        let metaLen = Int(leU32(b, n - 8))
        XCTAssertGreaterThan(metaLen, 0)
        // The metadata must sit entirely between the 4-byte header and the
        // 8-byte trailer.
        XCTAssertLessThanOrEqual(metaLen, n - 12)
        // The metadata region is a Thrift struct; its first byte is a field
        // header (non-zero), never a struct-stop (0x00).
        let metaStart = n - 8 - metaLen
        XCTAssertGreaterThanOrEqual(metaStart, 4)
        XCTAssertNotEqual(b[metaStart], 0x00)
    }

    func test_parquet_all_types_do_not_crash_and_have_envelope() {
        let samples = [
            #"[{"n":1},{"n":2},{"n":3}]"#,                    // required int64
            #"[{"n":1},{"n":2.5}]"#,                          // widened double
            #"[{"s":"a"},{"s":"b"}]"#,                        // string
            #"[{"o":{"k":1}},{"o":{"k":2}}]"#,                // json
            #"[{"f":true},{"f":false}]"#,                     // boolean
            #"[{"a":1,"b":7},{"a":2},{"a":3,"b":null}]"#,     // nullable
            "[1,2,3]",                                        // single value column
            "[]"                                              // empty
        ]
        for s in samples {
            let b = parquetBytes(s)
            XCTAssertGreaterThan(b.count, 12, "empty output for: \(s)")
            XCTAssertEqual(Array(b.prefix(4)), [0x50, 0x41, 0x52, 0x31], "bad header for: \(s)")
            XCTAssertEqual(Array(b.suffix(4)), [0x50, 0x41, 0x52, 0x31], "bad footer for: \(s)")
        }
    }

    func test_parquet_snappy_smaller_for_repetitive_data() throws {
        // 300 identical rows are highly compressible.
        let json = "[" + Array(repeating: #"{"n":7}"#, count: 300).joined(separator: ",") + "]"
        let table = try XCTUnwrap(json.parsed { $0?.toParquetTable() })
        let uncompressed = table.exportParquet(compression: .uncompressed)
        let snappy = table.exportParquet(compression: .snappy)

        XCTAssertLessThan(snappy.count, uncompressed.count,
                          "snappy should shrink repetitive data")
        // Both remain valid Parquet envelopes.
        for data in [uncompressed, snappy] {
            let b = [UInt8](data)
            XCTAssertEqual(Array(b.prefix(4)), [0x50, 0x41, 0x52, 0x31])
            XCTAssertEqual(Array(b.suffix(4)), [0x50, 0x41, 0x52, 0x31])
        }
    }

    func test_parquet_chunked_envelope_is_valid() throws {
        // 250 rows with a small row group and page size -> multiple row groups,
        // multiple pages per chunk. Structure must still be a valid envelope.
        let json = "[" + (0..<250).map { "{\"a\":\($0)}" }.joined(separator: ",") + "]"
        let opts = ParquetWriteOptions(rowsPerRowGroup: 100, rowsPerPage: 40)
        let data = try XCTUnwrap(json.parsed { $0?.toParquet(writeOptions: opts) })
        let b = [UInt8](data)
        XCTAssertGreaterThan(b.count, 12)
        XCTAssertEqual(Array(b.prefix(4)), [0x50, 0x41, 0x52, 0x31])
        XCTAssertEqual(Array(b.suffix(4)), [0x50, 0x41, 0x52, 0x31])
        let metaLen = Int(leU32(b, b.count - 8))
        XCTAssertGreaterThan(metaLen, 0)
        XCTAssertLessThanOrEqual(metaLen, b.count - 12)
    }

    // The streaming path (materialize per row-group slice) and the whole-table
    // path (materialize all, then slice) must produce byte-identical files for
    // the same options. Exercises multi-row-group, multi-page, and a nullable
    // column whose nulls straddle both boundaries.
    func test_parquet_streaming_matches_whole_table() throws {
        let rows = (0..<250).map { i in
            i % 4 == 0 ? "{\"a\":\(i)}" : "{\"a\":\(i),\"b\":\(i)}"
        }
        let json = "[" + rows.joined(separator: ",") + "]"
        let opts = ParquetWriteOptions(rowsPerRowGroup: 60, rowsPerPage: 25, compression: .snappy)

        let streamed = try XCTUnwrap(json.parsed { $0?.toParquet(writeOptions: opts) })
        let whole = try XCTUnwrap(json.parsed { $0?.toParquetTable().exportParquet(options: opts) })
        XCTAssertEqual([UInt8](streamed), [UInt8](whole))
    }

    // Opt-in: streams a real, multi-row-group Parquet file to disk for external
    // validation. No-op unless PARQUET_OUT is set, so it never fails CI. Small
    // row groups force chunking so validate.py reports several row groups.
    //
    //   PARQUET_OUT=/tmp/out.parquet swift test --filter test_parquet_write_file
    //   python3 validate.py /tmp/out.parquet
    func test_parquet_write_file() throws {
        guard let path = ProcessInfo.processInfo.environment["PARQUET_OUT"] else { return }
        let rows = (0..<500).map { i in
            i % 5 == 0
                ? "{\"id\":\(i),\"name\":\"row\(i)\"}"
                : "{\"id\":\(i),\"name\":\"row\(i)\",\"score\":\(Double(i) / 2.0),\"active\":\(i % 2 == 0)}"
        }
        let json = "[" + rows.joined(separator: ",") + "]"
        let opts = ParquetWriteOptions(rowsPerRowGroup: 150, rowsPerPage: 50, compression: .snappy)
        var written = 0
        var thrown: Error?
        json.parsed { element in
            guard let element = element else { return }
            do { written = try element.writeParquet(toFile: URL(fileURLWithPath: path), writeOptions: opts) }
            catch { thrown = error }
        }
        if let thrown = thrown { throw thrown }
        print("wrote \(written) bytes to \(path)")
    }
    
